{
  "name": "倍福PLC控制器",
  "name_en": "Beckhoff PLC controller",
  "manufacturer": "Beckhoff",
  "description": "一种用于工业自动化的可编程逻辑控制器（PLC）或工业控制器，可通过 ADS 暴露内部变量与符号。在实验室中常用于设备联锁、顺序控制、I/O 信号采集、执行器控制以及过程状态监测。",
  "description_en": "A programmable logic controller (PLC) or industrial controller used for industrial automation, exposing internal variables and symbols over ADS. In laboratory systems it is commonly used for equipment interlocks, sequence control, I/O acquisition, actuator control, and process-state monitoring.",
  "tag_hints": [
    "Beckhoff ADS",
    "TwinCAT PLC",
    "industrial automation",
    "process variables",
    "I/O monitoring",
    "equipment interlocks"
  ],
  "actions": [
    {
      "action_name": "auto-read",
      "description": "读取该 ADS 变量/符号的当前值。",
      "description_en": "Read the current value of this ADS variable/symbol."
    },
    {
      "action_name": "auto-write",
      "description": "向该 ADS 变量/符号写入新值或缓冲值。",
      "description_en": "Write a new value or the buffered value to this ADS variable/symbol."
    },
    {
      "action_name": "auto-add_device_notification",
      "description": "为该 ADS 变量添加变化通知回调。",
      "description_en": "Add a change-notification callback for this ADS variable."
    },
    {
      "action_name": "auto-clear_device_notifications",
      "description": "清除该 ADS 变量的全部通知。",
      "description_en": "Clear all notifications registered for this ADS variable."
    },
    {
      "action_name": "auto-del_device_notification",
      "description": "删除该 ADS 变量的单个通知。",
      "description_en": "Delete a single notification for this ADS variable."
    },
    {
      "action_name": "auto-auto_update",
      "description": "获取/设置符号缓冲值的自动更新状态。",
      "description_en": "Get/set the automatic update state of the symbol's buffered value."
    },
    {
      "action_name": "auto-value",
      "description": "获取/设置符号的当前值。",
      "description_en": "Get/set the current value of the symbol."
    },
    {
      "action_name": "auto-get_type_from_str",
      "description": "根据 PLC 类型字符串解析对应的数据类型。",
      "description_en": "Resolve the corresponding data type from a PLC type string."
    },
    {
      "action_name": "auto-is_structure",
      "description": "获取该符号是否为结构体类型。",
      "description_en": "Get whether this symbol represents a structure type."
    }
  ]
}

